"""What counts as a whole-mountain closure, and which conditions go with each kind. Reads data/derived/lift_days.csv, writes docs/CLOSURES.md.
usage: python3 -I scripts/closure_conditions.py   (run after build_dataset.py)"""
import csv, os, statistics as st, collections
ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..")
rows = list(csv.DictReader(open(os.path.join(ROOT, "data", "derived", "lift_days.csv"))))
def num(x): return float(x) if x not in ("", None) else None
days = {}
for r in rows:
    if r["in_season"] != "1" or not (r["scheduled"] == "True" or r["closed_all"] == "1"): continue
    d = days.setdefault((r["winter"], r["date"]), dict(winter=r["winter"], date=r["date"], gust=num(r["day_gust"]), h60=num(r["sib_h60"]), snow=num(r["new_snow24"]), swe=num(r["swe24"]), avy=num(r["avy"]), kind="", t="", sides=set()))
    if r["closed_all"] == "1":
        d["kind"] = r["closure_kind"] or d["kind"]; d["t"] = min([x for x in (d["t"], r["closed_all_time"]) if x] or [""]); d["sides"].add(r["side"])
D = list(days.values()); C = [d for d in D if d["kind"]]
def med(v): v = [x for x in v if x is not None]; return round(st.median(v), 1) if v else "n/a"
def rng(v): v = [x for x in v if x is not None]; return f"{min(v):.0f} to {max(v):.0f}" if v else "n/a"
def pct(a, b): return f"{100*a/b:.0f}%" if b else "n/a"
KIND = {"storm": "Storm", "lightning": "Lightning", "infrastructure": "Power or flooding", "schedule": "Schedule (no cause, spring)", "unstated": "Cause not stated"}
md = ["# What counts as a closure", "",
 "Generated by `python3 -I scripts/closure_conditions.py` from `data/derived/lift_days.csv`. Every number is counted from the posts and the weather files; nothing here is a fitted rule. Label: **derived** unless marked otherwise.", "",
 "## Definition used in this project", "",
 "- A **whole-mountain closure** is a post that closes every lift on a side or on both sides, with no lift named: \"Palisades Tahoe is CLOSED today\", \"ALL LIFTS CLOSED TODAY\", \"all lifts at Alpine are closed for the remainder of the day\", \"will not have any lift operations today\" (parser rule P-022, plus rule P-021 for \"all lifts ... closed\").",
 "- Its scope is one of: both sides, the Palisades side only, or the Alpine side only. The Base to Base Gondola counts as closed only when both sides are.",
 "- It is **not** a closure when: lifts are closed one by one, only the lifts already on hold are closed (that is scope ALL_ON_HOLD), a road, parking lot, tube park or trail is closed, a lift runs on limited operations (download only, mid-station only), or the closure is announced for a later day (that is a warning).",
 "- Time matters. The post time is kept (`closed_all_time`). A closure posted before 10am usually means the mountain never opened; one posted in the afternoon means lifts ran and then stopped.",
 "- The two sides do not always share a schedule. Palisades and Alpine can open and close on different days (Alpine often closes earlier in spring, Palisades can run into May or July 4th in big years), and the Base to Base Gondola keeps its own seasonal timeline. Season windows are kept per side in `rules/season_windows.json`; the gondola counts as in season when either side is. The split-schedule point is a general summary Evan pasted (unverified); the per-year dates in the season file are the evidence.", "",
 f"## Kinds of closure ({len(C)} days, eight winters)", "",
 "| Kind | Days | Median crest gust (mph) | Range | Hours at 60+ mph (median) | New snow (in, median) | Snow water (in, median) | Avalanche danger (median) | Median post time |", "|---|---|---|---|---|---|---|---|---|"]
for k, lab in KIND.items():
    x = [d for d in C if d["kind"] == k]
    if not x: continue
    ts = sorted(d["t"] for d in x if d["t"])
    md.append(f"| {lab} | {len(x)} | {med([d['gust'] for d in x])} | {rng([d['gust'] for d in x])} | {med([d['h60'] for d in x])} | {med([d['snow'] for d in x])} | {med([d['swe'] for d in x])} | {med([d['avy'] for d in x])} | {ts[len(ts)//2] if ts else 'n/a'} |")
md += ["", "**Storm** means the posts name wind, snow, avalanche danger, ice, low visibility or \"weather conditions\". **Lightning** closures happen mostly after noon and mostly in spring. **Schedule** closures are \"Alpine is closed today\"-style posts in April to June with no cause; they are operations, not conditions. **Cause not stated** is a closure post that names no cause; the conditions columns show what the weather was.", "",
 "## Conditions that go with a closure", ""]
n = len(D)
def share(sel): sel = list(sel); return f"{pct(sum(1 for d in sel if d['kind']), len(sel))} ({sum(1 for d in sel if d['kind'])} of {len(sel)})"
md += ["Share of in-season days (with at least one expected lift row) that had a whole-mountain closure:", "", "| Condition | Closure share of days |", "|---|---|"]
for lab, f in (("All in-season days", lambda d: True), ("Crest gust under 60 mph", lambda d: d["gust"] is not None and d["gust"] < 60), ("60 to 100 mph", lambda d: d["gust"] is not None and 60 <= d["gust"] < 100), ("100 to 130 mph", lambda d: d["gust"] is not None and 100 <= d["gust"] < 130), ("130 mph or more", lambda d: d["gust"] is not None and d["gust"] >= 130),
               ("Avalanche danger 1 to 2", lambda d: d["avy"] is not None and d["avy"] < 3), ("Avalanche danger 3", lambda d: d["avy"] is not None and round(d["avy"]) == 3), ("Avalanche danger 4", lambda d: d["avy"] is not None and round(d["avy"]) >= 4),
               ("Gust 100+ and danger 3+", lambda d: d["gust"] is not None and d["avy"] is not None and d["gust"] >= 100 and d["avy"] >= 3), ("Gust 100+ and 8+ hours at 60", lambda d: d["gust"] is not None and d["h60"] is not None and d["gust"] >= 100 and d["h60"] >= 8),
               ("Snow water 1.5 in or more in 24 hours", lambda d: d["swe"] is not None and d["swe"] >= 1.5), ("Wind under 60 and no storm signal", lambda d: d["gust"] is not None and d["gust"] < 60 and (d["avy"] or 0) < 3 and (d["swe"] or 0) < 1)):
    md.append(f"| {lab} | {share(d for d in D if f(d))} |")
S = [d for d in C if d["kind"] == "storm"]
_any = sum(1 for d in S if (d["gust"] is not None and d["gust"] >= 80) or (d["avy"] is not None and d["avy"] >= 3) or (d["swe"] is not None and d["swe"] >= 1.5))
md += ["", f"{_any} of the {len(S)} storm closures had at least one of: crest gust of 80 mph or more ({sum(1 for d in S if d['gust'] is not None and d['gust'] >= 80)}), avalanche danger 3 or higher ({sum(1 for d in S if d['avy'] is not None and d['avy'] >= 3)}), or snow water of 1.5 in or more ({sum(1 for d in S if d['swe'] is not None and d['swe'] >= 1.5)})." if S else "", "",
 "## Limits", "",
 "- Counts are small (a few dozen closure days), so shares move by several points with one day.",
 "- The kind comes from words in the post, which can name several causes; the tags are post-level, not sentence-level.",
 "- A closure is only as complete as the posts. The parser's closure rule was checked by hand on held-out posts (see `docs/PARSING_RULES.md`): it is the weakest part of the parser.",
 "- Avalanche danger is the Sierra Avalanche Center's forecast rating for the day; it is not the resort's own decision rule, which is unpublished."]
open(os.path.join(ROOT, "docs", "CLOSURES.md"), "w").write("\n".join(x for x in md if x is not None) + "\n")
print(f"{len(C)} closure days, {len(D)} days; wrote docs/CLOSURES.md")
